#' Select, update or modify coloraxis objects
#'
#' Work with all of a figure's layout coloraxis objects (\code{coloraxis}, \code{coloraxis2}, \code{coloraxis3}, ...).
#' \code{select_coloraxes()} returns them as a named list, \code{update_coloraxes()} updates
#' their properties like \code{\link{update_layout}()} does, and \code{for_each_coloraxis()}
#' replaces each one with the result of \code{fn}. The base object (e.g.
#' \code{coloraxis}) is always included, even if it has not been set yet.
#'
#' @param fig A \code{go_figure} object.
#' @param selector Which objects to use: \code{NULL} (all), indices into the
#'   matching objects, a named list of property values that must all match,
#'   or a function that takes an object and returns \code{TRUE} or \code{FALSE}.
#' @param row,col Only objects in this subplot grid row and/or column
#'   (figures created with \code{\link{make_subplots}()} only).
#' @param patch A named list or \code{\link{go_layout_coloraxis}()} object of property updates.
#' @param ... Further named updates (names may use magic underscores).
#' @param overwrite If \code{TRUE}, replace nested objects instead of merging.
#' @param fn A function that takes an object and returns the modified object.
#'   If it returns anything other than a list, the object is left unchanged.
#' @return \code{select_coloraxes()} returns a named list of \code{\link{go_layout_coloraxis}()} objects; the
#'   others return the modified figure.
#' @name update_coloraxes
#' @noMd
NULL

#' @rdname update_coloraxes
#' @export
select_coloraxes <- function(fig, selector = NULL, row = NULL, col = NULL) {
  select_layout_subplots(fig, "coloraxis", selector, row, col)
}

#' @rdname update_coloraxes
#' @export
update_coloraxes <- function(fig, patch = NULL, ..., selector = NULL, row = NULL, col = NULL, overwrite = FALSE) {
  update_layout_subplots(fig, "coloraxis", patch, selector, list(...), overwrite, row, col)
}

#' @rdname update_coloraxes
#' @export
for_each_coloraxis <- function(fig, fn, selector = NULL, row = NULL, col = NULL) {
  for_each_layout_subplot(fig, "coloraxis", fn, selector, row, col)
}

